mapper.select:
SELECT DATE_FORMAT( need.ask_complete_time, '%Y-%m' ) FROM mes_building_task_need_machine_part_scheduling need LEFT JOIN tech_machine_part machine_part ON machine_part.id = need.product_id and machine_part.bool_delete_enum = 0 WHERE need.bool_delete_enum = 0
AND need.send_nesting_status = #{sendStatus}
AND need.workshop_id in
#{item}
AND machine_part.steel_plate_type_enum in
#{item}
GROUP BY DATE_FORMAT( need.ask_complete_time, '%Y-%m' )
HAVING SUM(need.need_quantity - need.scheduling_quantity) > 0

SELECT a.product_id AS id, a.project_id 'project.id', pro.`name` 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', a.monomer_id 'monomer.id', mon.`name` 'monomer.name', a.area_id 'area.id', area.`name` 'area.name', a.workshop_id 'workshop.id', shop.`name` 'workshop.name', a.production_line_id 'productionLine.id', line.`name` 'productionLine.name', a.groups_id 'group.name', bgroups.`name` 'group.name', a.quantity 'quantity', par.net_weight 'netWeight', a.quantity * par.net_weight 'totalNetWeight', par.gross_weight 'grossWeight', par.relation_type 'relationType', par.material 'material', par.serial_number 'serialNumber', par.name 'name', par.specification 'specification', par.length 'length', par.thick 'thick', if(draw.picture_path!=null,1,0), a.quantity * par.gross_weight 'totalGrossWeight', draw.picture_path 'picturePath', a.maxAskCompleteTime 'maxAskCompleteTime', a.minAskCompleteTime 'minAskCompleteTime' FROM ( SELECT need.project_id, need.monomer_id, need.area_id, need.workshop_id, need.production_line_id, need.groups_id, need.product_id , SUM(need.need_quantity - need.scheduling_quantity) quantity, MAX(ask_complete_time) 'maxAskCompleteTime', MIN(ask_complete_time) 'minAskCompleteTime' FROM mes_building_task_need_machine_part_scheduling need WHERE need.bool_delete_enum = 0 AND need.need_quantity > need.scheduling_quantity
AND need.project_id IN
#{projectId}
AND need.monomer_id IN
#{monomerId}
AND need.area_id IN
#{areaId}
AND DATE_FORMAT(need.ask_complete_time, '%Y-%m') IN
DATE_FORMAT( #{month}, '%Y-%m' )
AND need.workshop_id IN
#{shopId}
AND need.production_line_id IN
#{lineId}
AND need.groups_id IN
#{groupsId}
GROUP BY need.product_id , need.project_id, need.monomer_id, need.area_id, need.workshop_id, need.production_line_id, need.groups_id ) a LEFT JOIN contract_project pro ON a.project_id = pro.id and pro.bool_delete_enum=0 LEFT JOIN plan_monomer mon ON a.monomer_id = mon.id and mon.bool_delete_enum=0 LEFT JOIN plan_area area ON a.area_id = area.id and area.bool_delete_enum=0 LEFT JOIN mes_building_workshop shop ON a.workshop_id = shop.id and shop.bool_delete_enum=0 LEFT JOIN mes_building_production_line line ON a.production_line_id = line.id and line.bool_delete_enum=0 LEFT JOIN mes_building_groups bgroups ON a.groups_id = bgroups.id and bgroups.bool_delete_enum=0 LEFT JOIN tech_machine_part par ON a.product_id = par.id and par.bool_delete_enum=0 LEFT JOIN tech_drawing draw ON par.monomer_id = draw.monomer_id and draw.bool_delete_enum=0 AND par.serial_number = draw.serial_number AND draw.data_type = 2 AND draw.product_type = 1 where 1=1
AND par.relation_type&#{taskTypeEnum}
AND par.material=#{material}
AND par.thick in
#{thick}
AND par.material=#{material}
AND par.length>=#{minLength}
AND #{maxLength}>= par.length
AND draw.picture_path is NOT NULL
AND draw.picture_path is NULL

SELECT a.project_id 'project.id', pro.`name` 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', a.monomer_id 'monomer.id', mon.`name` 'monomer.name', a.area_id 'area.id', area.`name` 'area.name', a.workshop_id 'workshop.id', shop.`name` 'workshop.name', a.production_line_id 'productionLine.id', line.`name` 'productionLine.name', a.groups_id 'group.name', bgroups.`name` 'group.name', a.quantity 'quantity', par.net_weight 'netWeight', a.quantity * par.net_weight 'totalNetWeight', par.gross_weight 'grossWeight', par.relation_type 'relationType', par.material 'material', par.serial_number 'serialNumber', par.name 'name', par.specification 'specification', par.length 'length', par.thick 'thick', if(draw.picture_path!=null,1,0), a.quantity * par.gross_weight 'totalGrossWeight', draw.picture_path 'picturePath', a.maxAskCompleteTime 'maxAskCompleteTime', a.minAskCompleteTime 'minAskCompleteTime' FROM ( SELECT need.project_id, need.monomer_id, need.area_id, need.workshop_id, need.production_line_id, need.groups_id, need.product_id , SUM(need.need_quantity - need.scheduling_quantity) quantity, MAX(ask_complete_time) 'maxAskCompleteTime', MIN(ask_complete_time) 'minAskCompleteTime' FROM mes_building_task_need_machine_part_scheduling need WHERE need.bool_delete_enum = 0 AND need.need_quantity > need.scheduling_quantity
AND need.project_id IN
#{projectId}
AND need.monomer_id IN
#{monomerId}
AND need.area_id IN
#{areaId}
AND DATE_FORMAT(need.ask_complete_time, '%Y-%m') IN
DATE_FORMAT( #{month}, '%Y-%m' )
AND need.workshop_id IN
#{shopId}
AND need.production_line_id IN
#{lineId}
AND need.groups_id IN
#{groupsId}
GROUP BY need.product_id , need.project_id, need.monomer_id, need.area_id, need.workshop_id, need.production_line_id, need.groups_id ) a LEFT JOIN contract_project pro ON a.project_id = pro.id and pro.bool_delete_enum=0 LEFT JOIN plan_monomer mon ON a.monomer_id = mon.id and mon.bool_delete_enum=0 LEFT JOIN plan_area area ON a.area_id = area.id and area.bool_delete_enum=0 LEFT JOIN mes_building_workshop shop ON a.workshop_id = shop.id and shop.bool_delete_enum=0 LEFT JOIN mes_building_production_line line ON a.production_line_id = line.id and line.bool_delete_enum=0 LEFT JOIN mes_building_groups bgroups ON a.groups_id = bgroups.id and bgroups.bool_delete_enum=0 LEFT JOIN tech_machine_part par ON a.product_id = par.id and par.bool_delete_enum=0 LEFT JOIN tech_drawing draw ON par.monomer_id = draw.monomer_id and draw.bool_delete_enum=0 AND par.serial_number = draw.serial_number AND draw.data_type = 2 AND draw.product_type = 1 where 1=1
AND par.relation_type&#{taskTypeEnum}
AND par.steel_plate_type_enum=#{steelPlateTypeEnum}
AND par.material=#{material}
AND par.thick in
#{thick}
AND par.material=#{material}
AND par.length>=#{minLength}
AND #{maxLength}>= par.length
AND draw.picture_path is NOT NULL
AND draw.picture_path is NULL
